// Practical TypeScript Example: Cross-Browser Compatibility & Runtime Quirks of Interfaces vs Type Aliases: Declaration Merging & Performance
interface UserAccount {
  readonly id: string;
  name: string;
  email: string;
  role: 'STUDENT' | 'MENTOR' | 'ADMIN';
}

function sendWelcomeNotification(user: UserAccount): string {
  console.log(`Sending welcome email to ${user.email}...`);
  return `Welcome, ${user.name}! Your account role is ${user.role}.`;
}

const candidate: UserAccount = {
  id: "USR-401",
  name: "Sneha",
  email: "sneha@prep.in",
  role: "STUDENT"
};

console.log(sendWelcomeNotification(candidate));

